import React from "react";
import Engine from "./engine";
import ReactRenderer from "./reactRenderer";
import * as Runtime from "runtime";
import { createContext } from "react";

export const AppContext = createContext();

export const reactEngine = {
  components: ["React"],
  update(actor) {
    let root = Engine.getReactRootForActor(actor.id);
    let Component = Engine.getReactComponent(actor.React.reactComponent);

    let props = actor.React;
    if (actor.React.mapPropsFrom) {
      props = { ...props, ...actor[actor.React.mapPropsFrom] };
    }

    ReactRenderer.render(<Component {...props} rootActor={actor} />, root);
  },
  resize(actor) {
    actor.screenWidth = Runtime.getScreenLeft();
    console.log("resize for actor!", actor.screenWidth);
  },
};
