import React from "react";

import TitleText from "./components/TitleText";
import StatusText from "./components/StatusText";

import { ActionButton, buttonEngine } from "./components/ActionButton";

import { BlinkText } from "./components/BlinkText";

import Engine from "../engine";

import { ProfileResults } from "./components/ProfileResults";
import TileMap from "./components/TileMap";
import Player from "./components/Player";

import { Items } from "./components/Items";
import { generateMapSeed, getMapSeedFloor } from "./utils/mapSeed";

export const mainGameEngine = {
  components: ["MainGame"],
  update: ({ MainGame }) => {
    let world = Engine.getActor(MainGame.world);
    let player = Engine.getActor(MainGame.player);

    if (!player) {
      return;
    }

    let destX = -player.Rect.localX * world.Rect.scale;
    let destY = -player.Rect.localY * world.Rect.scale;
    world.Rect.x += (destX - world.Rect.x) / MainGame.cameraLerp;
    world.Rect.y += (destY - world.Rect.y) / MainGame.cameraLerp;

    switch (MainGame.mode) {
      case "game":
        if (player.Character.dead) {
          MainGame.mode = "dead";
          world.Tweens = [
            {
              target: "Rect.scale",
              ease: "InOutSine",
              duration: 4,
              start: world.Rect.scale,
              destination: 3,
              startTime: 0,
            },
          ];
        }
        break;
    }
  },
  playerGoDownStairs(actor, action) {
    actor.MainGame.cameraLerp = 1;
    let world = Engine.getActor(actor.MainGame.world);
    world.Tweens = [
      {
        target: "Rect.scale",
        ease: "InOutSine",
        duration: 0.5,
        start: world.Rect.scale,
        destination: 5,
        onCompleteSystemEvent: "playerGoDownStairsDoIt",
        onCompleteParam: action,
        startTime: 0,
      },
    ];
  },
  playerGoDownStairsDoIt(actor, action) {
    actor.MainGame.cameraLerp = 10;
    actor.MainGame.mapSeed = action.seed;

    let player = Engine.getActor(actor.MainGame.player);
    player.Position.x = action.toX;
    player.Position.y = action.toY;
    player.Rect.localX = action.toX * 32;
    player.Rect.localY = action.toY * 32;

    let world = Engine.getActor(actor.MainGame.world);

    world.Rect.x = -player.Rect.localX * world.Rect.scale;
    world.Rect.y = -player.Rect.localY * world.Rect.scale;

    world.Tweens = [
      {
        target: "Rect.scale",
        ease: "InOutSine",
        duration: 1,
        start: world.Rect.scale,
        destination: 2,
        startTime: 0,
      },
    ];
  },
  profileResults(actor, results) {
    actor.React.profileResults = results;
  },
  restartGame(actor) {
    actor.MainGame.mapSeed = generateMapSeed(1);
    actor.MainGame.mode = "game";
    let world = Engine.getActor(actor.MainGame.world);
    actor.MainGame.session++;
    world.Tweens = [
      {
        target: "Rect.scale",
        ease: "InOutSine",
        duration: 4,
        start: world.Rect.scale,
        destination: 2,
        startTime: 0,
      },
    ];
  },
  getfps(actor, fps) {
    actor.React.fps = fps;
  },
};

export const createMainGame = () => {
  let mapSeed = generateMapSeed(1);

  let world = Engine.createActor({
    Rect: {
      x: -200,
      y: -300,
      scale: 0.5,
    },
    Tweens: [
      {
        target: "Rect.scale",
        ease: "InOutSine",
        duration: 10,
        start: 1,
        destination: 2,
        startTime: 0,
      },
    ],
  });

  let mainGame = Engine.createActor({
    MainGame: {
      mode: "game",
      world: world.id,
      mapSeed: mapSeed,
      cameraLerp: 10,
      player: null,
      session: 0,
    },
    React: {
      reactComponent: "Game",
      mapPropsFrom: "MainGame",
      mapElementsTo: "MainGame",
      screenWidth: 0,
      profileResults: "",
      fps: 0,
    },
    CharacterController: {
      currentCharacterIndex: 0,
    },
  });
  return mainGame;
};

export const Game = (props) => {
  let { MainGame } = props.rootActor;
  let player = Engine.getActor(props.player);

  return (
    <group key={props.session}>
      {/* <ProfileResults text={props.profileResults} fps={props.fps} /> */}
      <TileMap world={props.world} mapSeed={props.mapSeed} />
      <Items world={props.world} mapSeed={props.mapSeed} />
      <Player world={props.world} mapSeed={props.mapSeed} mapTo="player" />
      {props.mode == "menu" && (
        <>
          <TitleText y={-50} text="Ner" />
          <BlinkText y={300} text={"Start Game"} />
        </>
      )}
      {player && player?.Character.availableAction && (
        <ActionButton
          y={250}
          text={"Action: " + player?.Character?.availableAction.name}
          event="doPlayerAction"
        />
      )}

      {player && player?.Character.dead && (
        <>
          <ActionButton
            key="restart"
            y={250}
            text={"Restart game"}
            event="restartGame"
            name="RestartButton"
          />
          <TitleText y={-50} text="Game over" />
        </>
      )}

      {player && <StatusText y={200} text={"Gold: " + player?.Character?.gold} />}
    </group>
  );
};
