export const nativeSprite = {
  name: "Sprite",
  create(component) {
    return new NativeEngines.Sprite(component.name, Engine.atlas, component.alpha);
  },
};

export const nativeRect = {
  name: "Rect",
  create(component) {
    return new NativeEngines.Rect(
      component.x,
      component.y,
      component.localX,
      component.localY,
      component.width,
      component.height,
      component.alignX,
      component.alignY,
      component.scale ?? 1,
      component.hidden
    );
  },
};

export const graphicsEngine = {
  components: ["GraphicsRect", "Rect"],
  update: (actor) => {
    //console.log("drawing at ", actor.Rect.x);

    let x = actor.Rect.x;
    let y = actor.Rect.y;
    if (!actor.ParentRect) {
      /*if (actor.Rect.localX) {
          x = actor.Rect.localX;
        }
        if (actor.Rect.localY) {
          y = actor.Rect.localY;
        }*/
    }

    let anchorX = 0;
    if (actor.Rect.anchorX) {
      anchorX = actor.Rect.anchorX;
    }

    let anchorY = 0;
    if (actor.Rect.anchorY) {
      anchorY = actor.Rect.anchorY;
    }

    Runtime.graphicsBeginPath();
    Runtime.graphicsFillColor(0, 0, 0, 0.5);
    Runtime.graphicsRect(
      x - actor.Rect.width * 0.5 - actor.Rect.width * 0.5 * anchorX,
      y - actor.Rect.height * 0.5 - actor.Rect.height * 0.5 * anchorY,
      actor.Rect.width,
      actor.Rect.height
    );
    Runtime.graphicsFill();
    //Engine.drawAtlasFrame(atlas, actor.Sprite.name, x, y, 0, 0, 0, actor.Rect.scale, 1);
  },
};

export const velocityEngine = {
  components: ["Rect", "Velocity"],
  update: (actor) => {
    if (actor.ParentRect) {
      actor.Rect.localX += actor.Velocity.x;
      actor.Rect.localY += actor.Velocity.y;
    } else {
      actor.Rect.x += actor.Velocity.x;
      actor.Rect.y += actor.Velocity.y;
    }
    if (actor.Velocity.gravity) {
      actor.Velocity.y += actor.Velocity.gravity;
    }
  },
};

export const randomSpriteAnimationEngine = {
  components: ["Sprite", "RandomSpriteAnimation"],
  update: (actor) => {
    if (
      Date.now() - actor.RandomSpriteAnimation.lastChangeTime >
      actor.RandomSpriteAnimation.minimumWait
    ) {
      if (Math.random() > actor.RandomSpriteAnimation.randomChange) {
        actor.RandomSpriteAnimation.lastChangeTime = Date.now();
        actor.Sprite.name =
          actor.RandomSpriteAnimation.frames[
            Math.floor(Math.random() * actor.RandomSpriteAnimation.frames.length)
          ];

        /*let frame = atlas.frames[actor.Sprite.name].frame;
          actor.Rect.width = frame.w * actor.Rect.scale;
          actor.Rect.height = frame.h * actor.Rect.scale;*/
      }
    }
  },
};

export const parentEngine = {
  components: ["Rect", "ParentRect"],
  update: (actor) => {
    // should be sorted somehow??
    let parent = Engine.getActor(actor.ParentRect);

    if (!parent) {
      /*if (actor.Alien) {
          console.log("killing this because dead ", actor.ParentRect);
        }*/

      Engine.killActor(actor.id);
      return;
    }
    let anchorX = parent.Rect.anchorX || 0;
    let anchorY = parent.Rect.anchorY || 0;

    let halfWidth = (parent.Rect.width || 0) * 0.5;
    let halfHeight = (parent.Rect.height || 0) * 0.5;

    let parentX = parent.Rect.x;
    let parentY = parent.Rect.y;
    let parentScale = parent.Rect.scale ?? 1;

    if (!parent.ParentRect) {
      if (parent.Rect.localX) {
        parentX = parent.Rect.localX;
      }
      if (parent.Rect.localY) {
        parentY = parent.Rect.localY;
      }
    }

    parentX = parentX - halfWidth - halfWidth * anchorX;
    parentY = parentY - halfHeight - halfHeight * anchorY;
    actor.Rect.x = parentX + actor.Rect.localX * parentScale;
    actor.Rect.y = parentY + actor.Rect.localY * parentScale;
    actor.Rect.scale = (actor.Rect.localScale ?? 1) * parentScale;
  },
};

export const boundsKillerEngine = {
  components: ["Rect", "BoundsKiller"],
  update(actor) {
    if (actor.Rect.y < actor.BoundsKiller.top || actor.Rect.y > actor.BoundsKiller.bottom) {
      Engine.killActor(actor.id);
    }
  },
};

export const timeKillerEngine = {
  components: ["TimeKiller"],
  update(actor) {
    if (Date.now() > actor.TimeKiller.time) {
      Engine.killActor(actor.id);
    }
  },
};

export const textEngine = {
  components: ["Rect", "Text"],
  update(actor) {
    if (actor.Rect.hidden) {
      return;
    }
    Runtime.graphicsFontSize(actor.Text.size);
    Runtime.graphicsFontFace(actor.Text.font);
    Runtime.graphicsFillColor(1, 1, 1, 1);
    let align = 0;
    if (actor.Text.align && actor.Text.align == "center") {
      align = 2;
    }

    if (actor.Text.verticalAlign && actor.Text.verticalAlign == "center") {
      align |= 16;
    }
    Runtime.graphicsTextAlign(align);

    Runtime.graphicsText(actor.Rect.x, actor.Rect.y, actor.Text.text);
  },
};

export const textBoxEngine = {
  components: ["Rect", "TextBox"],
  update(actor) {
    if (actor.Rect.hidden) {
      return;
    }
    Runtime.graphicsFontSize(actor.TextBox.size);
    Runtime.graphicsFontFace(actor.TextBox.font);
    Runtime.graphicsFillColor(1, 1, 1, 1);

    if (actor.TextBox.align && actor.TextBox.align == "center") {
      Runtime.graphicsTextAlign(2);
    } else {
      Runtime.graphicsTextAlign(1);
    }

    Runtime.graphicsTextBox(actor.Rect.x, actor.Rect.y, actor.Rect.width, actor.TextBox.text);
  },
};

export const tileEngine = ({ getCurrentMapSeed }) => {
  return {
    components: ["Rect", "Tile", "Position"],
    update(actor) {
      if (actor.Position.mapSeed != getCurrentMapSeed()) {
        return;
      }

      let x = actor.Rect.x;
      let y = actor.Rect.y;

      Engine.drawTile(actor.Tile.index, x, y, actor.Rect.scale);
    },
  };
};

function easeInOutSine(x) {
  return -(Math.cos(Math.PI * x) - 1) / 2;
}

let unpackOne = function (o, path) {
  if (o == null) {
    return;
  } else {
    return o[path];
  }
};

let delve = function (o, path) {
  let parts = path.split(".");
  let result = o;
  let part;

  while (parts.length) {
    part = parts.shift();
    result = unpackOne(result, part);
  }

  return result;
};

function dset(obj, keys, val) {
  keys.split && (keys = keys.split("."));
  var i = 0,
    l = keys.length,
    t = obj,
    x,
    k;
  while (i < l) {
    k = keys[i++];
    if (k === "__proto__" || k === "constructor" || k === "prototype") break;
    t = t[k] =
      i === l
        ? val
        : typeof (x = t[k]) === typeof keys
        ? x
        : keys[i] * 0 !== 0 || !!~("" + keys[i]).indexOf(".")
        ? {}
        : [];
  }
}

export const tweenEngine = {
  components: ["Tweens"],
  update(actor) {
    if (actor.TweenQueue) {
      if (actor.Tweens.length == 0 && actor.TweenQueue.length > 0) {
        actor.Tweens = actor.TweenQueue.shift();
      }
    }

    for (let i = actor.Tweens.length - 1; i >= 0; i--) {
      let tween = actor.Tweens[i];

      if (tween.startTime == 0) {
        tween.startTime = globalThis.__date_clock();
      }

      let elapsed = globalThis.__date_clock() - tween.startTime;

      if (tween.delay) {
        if (elapsed < tween.delay * 1000000) {
          continue;
        }
        tween.delay = 0;
        tween.startTime = 0;
        continue;
      }
      let progress = elapsed / (tween.duration * 1000000);
      let diff = tween.destination - tween.start;
      let current = tween.start + easeInOutSine(progress) * diff;
      dset(actor, tween.target, current);
      if (progress > 1) {
        actor.Tweens.splice(i, 1);
        if (tween.onCompleteEvent) {
          Engine.handleEventForActor(actor.id, tween.onCompleteEvent, tween.onCompleteParam);
        }
        if (tween.onCompleteSystemEvent) {
          Engine.handleEventForEngines(tween.onCompleteSystemEvent, tween.onCompleteParam);
        }
      }
    }
  },
  kill(actor) {
    Engine.killActor(actor.id);
  },
};
