import Engine from "../../engine";

export const characterSystem = ({ isWalkableTileAt, getCurrentMapSeed }) => {
  // this should query a grid collision system instaed
  const getCharacterAt = (mapSeed, x, y) => {
    let characters = Engine.getActorsWithComponent("Character");
    for (let character of characters) {
      if (
        character.Position.mapSeed == mapSeed &&
        character.Position.x == x &&
        character.Position.y == y
      ) {
        return character;
      }
    }
    return null;
  };

  const performCommand = (character) => {
    let tryCommand = character.Character.command;
    character.Character.command = null;

    if (character.Character.dead) {
      return true;
    }

    switch (tryCommand) {
      case "UP":
        return tryMoveCharacter(character, 0, -1);
      case "UPLEFT":
        return tryMoveCharacter(character, -1, -1);
      case "UPRIGHT":
        return tryMoveCharacter(character, 1, -1);
      case "DOWN":
        return tryMoveCharacter(character, 0, 1);
      case "DOWNLEFT":
        return tryMoveCharacter(character, -1, 1);
      case "DOWNRIGHT":
        return tryMoveCharacter(character, 1, 1);
      case "LEFT":
        return tryMoveCharacter(character, -1, 0);
      case "RIGHT":
        return tryMoveCharacter(character, 1, 0);
      case "ATTACK":
        return attackCharacter(character, character.Character.attackTarget);
    }
  };

  const attackCharacter = (attacker, targetId) => {
    let target = Engine.getActor(targetId);

    if (attacker.Character.busy || target.Character.busy) {
      // if target is busy animating
      // then delay attack to next frame
      attacker.Character.command = "ATTACK";
      attacker.Character.wait = true;
      return false;
    }
    attacker.Character.wait = false;
    target.Character.health--;

    if (target.Character.health <= 0) {
      Engine.handleEventForActor(target.id, "die");
      if (!target.Character.hero) {
        Engine.killActor(target.id);
      }
    }

    console.log(
      "Attacked target " + targetId + " target now has health " + target.Character.health
    );

    Engine.createActor({
      Rect: {
        x: 0,
        y: 0,
        localX: target.Rect.localX,
        localY: target.Rect.localY,
        localScale: 1,
      },
      ParentRect: target.ParentRect,
      Position: {
        mapSeed: target.Position.mapSeed,
        x: target.Position.x,
        y: target.Position.y,
      },
      Tile: {
        index: 22 * 40 + 37,
      },
      Tweens: [
        {
          target: "Rect.localScale",
          ease: "InOutSine",
          duration: 0.2,
          start: 1,
          destination: 0,
          startTime: 0,
          onCompleteEvent: "kill",
        },
      ],
    });

    return true;
  };

  const tryMoveCharacter = (character, moveX, moveY) => {
    let newPosX = character.Position.x + moveX;
    let newPosY = character.Position.y + moveY;

    if (!isWalkableTileAt(character.Position.mapSeed, newPosX, newPosY)) {
      return false;
    }

    let enemy = getCharacterAt(character.Position.mapSeed, newPosX, newPosY);
    if (enemy) {
      character.Character.command = "ATTACK";
      character.Character.attackTarget = enemy.id;
      return false;
    }

    let delay = 0;
    let duration = 0.15;
    if (!character.Character.hero && !character.Character.busy) {
      delay = 0.1 + Math.random() * 0.2;
      duration = 0.2;
    }

    if (character.Character.hero) {
      duration = 0.2;
    }

    character.Character.busy = true;
    let tweens = [];
    let tween = {
      target: "Rect.localX",
      ease: "InOutSine",
      delay: delay,
      duration: duration,
      start: character.Position.x * 32,
      destination: newPosX * 32,
      startTime: 0,
    };
    character.Position.x = newPosX;
    tweens.push(tween);

    tween = {
      target: "Rect.localY",
      ease: "InOutSine",
      delay: delay,
      duration: duration,
      start: character.Position.y * 32,
      destination: newPosY * 32,
      startTime: 0,
      onCompleteEvent: "turnDone",
    };
    character.Position.y = newPosY;
    tweens.push(tween);
    character.TweenQueue.push(tweens);
    character.Character.availableAction = null;

    Engine.handleEventForEngines("playerMoved", character);

    return true;
  };

  return {
    components: ["CharacterController"],
    update(actor) {
      let characters = Engine.getActorsWithComponent("Character");
      if (characters.length == 0) {
        return;
      }
      while (true) {
        // for (let character of characters) {
        //   if (character.Character.busy) {
        //     return;
        //   }
        // }

        let currentCharacter =
          characters[actor.CharacterController.currentCharacterIndex % characters.length];

        let isHero = currentCharacter.Character.hero;

        if (!isHero && currentCharacter.Position.mapSeed != getCurrentMapSeed()) {
          actor.CharacterController.currentCharacterIndex++;
          continue;
        }

        currentCharacter.Character.energy += currentCharacter.Character.speed;

        if (currentCharacter.Character.energy >= 1) {
          if (!currentCharacter.Character.command) {
            if (!isHero) {
              Engine.handleEventForActor(currentCharacter.id, "advanceAI");
              //continue;
            } else {
              return;
            }
          }
          if (isHero && currentCharacter.Character.busy) {
            return;
          }

          let success = performCommand(currentCharacter);
          if (!success) {
            if (!isHero && !currentCharacter.Character.wait) {
              continue;
            }
            return;
          }
          currentCharacter.Character.energy = 0;
        }
        actor.CharacterController.currentCharacterIndex++;
      }
    },
  };
};

export const characterCommandSystem = {
  components: ["Character", "Tweens"],
  turnDone(actor) {
    if (actor.TweenQueue.length == 0) {
      actor.Character.busy = false;
    }
  },
  die(actor) {
    actor.Character.dead = true;
    actor.Tile.index = 21 * 40 + 38;
  },
};
