import React from "react";

export const blinkEngine = {
  components: ["Rect", "Blink"],
  update: (actor) => {
    actor.Rect.hidden = Date.now() % actor.Blink.interval > actor.Blink.interval / 2;
  },
};

export const BlinkText = (props) => {
  return (
    <actor
      components={{
        Rect: {
          x: 0,
          y: props.y,
          width: 1000,
          height: 30,
          hidden: false,
        },
        Blink: {
          interval: 1000,
        },
        Text: {
          font: "blackcastle.ttf",
          size: 50,
          text: props.text,
          align: "center",
        },
      }}
      updateValues={{
        Text: {
          text: props.text,
        },
      }}
    />
  );
};
