import React, { useRef } from "react";
import Engine from "../../engine";

import { isWalkableTileAt, getTileMap } from "../../tileMapEngine";
import { aleaPRNG } from "../../lib/alea";
import { generateMapSeed, getMapSeedFloor } from "../utils/mapSeed";

export let findRandomItemPosition = (mapSeed, randomNumbers) => {
  let map = getTileMap(mapSeed);

  let x = 0;
  let y = 0;
  for (let i = 0; i < 20; i++) {
    let randX = randomNumbers.range(0, map.width);
    let randY = randomNumbers.range(0, map.height);
    if (isWalkableTileAt(mapSeed, randX, randY)) {
      return [randX, randY];
    }
  }
};

let createItems = (seed, world) => {
  let randomNumbers = aleaPRNG(seed);

  let items = [];

  let [placeX, placeY] = findRandomItemPosition(seed, randomNumbers);
  let floor = getMapSeedFloor(seed);
  let toSeed = generateMapSeed(floor + 1);

  let [upPlaceX, upPlaceY] = findRandomItemPosition(toSeed, randomNumbers);

  let stairs = Engine.createActor({
    Rect: {
      x: 0,
      y: 0,
      localX: placeX * 32,
      localY: placeY * 32,
    },
    ParentRect: world,
    Position: {
      mapSeed: seed,
      x: placeX,
      y: placeY,
    },
    Item: {
      type: "stairdown",
      toSeed: toSeed,
      toX: upPlaceX,
      toY: upPlaceY,
    },
    Tile: {
      index: 21 * 40 + 34,
    },
  });

  items.push(stairs.id);

  let upStairs = Engine.createActor({
    Rect: {
      x: 0,
      y: 0,
      localX: upPlaceX * 32,
      localY: upPlaceY * 32,
    },
    ParentRect: world,
    Position: {
      mapSeed: toSeed,
      x: upPlaceX,
      y: upPlaceY,
    },
    Item: {
      type: "stairup",
      toSeed: seed,
      toX: placeX,
      toY: placeY,
    },
    Tile: {
      index: 21 * 40 + 33,
    },
  });

  items.push(upStairs.id);

  [placeX, placeY] = findRandomItemPosition(seed, randomNumbers);

  let gold = Engine.createActor({
    Rect: {
      x: 0,
      y: 0,
      localX: placeX * 32,
      localY: placeY * 32,
    },
    ParentRect: world,
    Position: {
      mapSeed: seed,
      x: placeX,
      y: placeY,
    },
    Item: {
      type: "gold",
      amount: 100,
    },
    Tile: {
      index: 20 * 40 + 7,
    },
  });

  items.push(gold.id);

  [placeX, placeY] = findRandomItemPosition(seed, randomNumbers);

  let enemy = Engine.createActor({
    Rect: {
      x: 0,
      y: 0,
      localX: placeX * 32,
      localY: placeY * 32,
    },
    ParentRect: world,
    Position: {
      mapSeed: seed,
      x: placeX,
      y: placeY,
    },
    Tile: {
      index: 5 * 40 + 5,
    },
    Tweens: [],
    TweenQueue: [],
    Character: {
      health: 3,
      availableAction: null,
      gold: 0,
      command: null,
      busy: false,
      wait: false,
      speed: 0.12,
      energy: 0,
      target: null,
    },
    EnemyAI: true,
  });

  items.push(enemy.id);

  [placeX, placeY] = findRandomItemPosition(seed, randomNumbers);

  enemy = Engine.createActor({
    Rect: {
      x: 0,
      y: 0,
      localX: placeX * 32,
      localY: placeY * 32,
    },
    ParentRect: world,
    Position: {
      mapSeed: seed,
      x: placeX,
      y: placeY,
    },
    Tile: {
      index: 5 * 40 + 10,
    },
    Tweens: [],
    TweenQueue: [],
    Character: {
      health: 5,
      availableAction: null,
      gold: 0,
      command: null,
      busy: false,
      wait: false,
      speed: 0.08,
      energy: 0,
      target: null,
    },
    EnemyAI: true,
  });

  items.push(enemy.id);

  return items;
};

export const Items = React.memo((props) => {
  return (
    <actor
      components={{
        Rect: {
          x: 0,
          y: 0,
          localX: 0,
          localY: 0,
        },
        ParentRect: props.world,
        Children: [],
        MapSeeds: [],
      }}
      updateValues={(actor) => {
        // check if this floor exists, otherwise spawn stuff
        if (!actor.MapSeeds.find((item) => item == props.mapSeed)) {
          actor.MapSeeds.push(props.mapSeed);
          let items = createItems(props.mapSeed, props.world);
          actor.Children = [...actor.Children, ...items];
        }
      }}
    />
  );
});
