import React from "react";
import Engine from "../../engine";
import { isInsideRect } from "../../utils/rect";

export const buttonEngine = {
  components: ["Button"],
  mouseup(actor, event) {
    if (isInsideRect(event.x, event.y, actor.Rect)) {
      Engine.handleEventForEngines(actor.Button.event);
    }
  },
  touchend(actor, event) {
    if (isInsideRect(event.x, event.y, actor.Rect)) {
      Engine.handleEventForEngines(actor.Button.event);
    }
  },
};

export const ActionButton = (props) => {
  return (
    <actor
      components={{
        Rect: {
          x: 0,
          y: props.y,
          width: 200,
          height: 50,
        },
        Text: {
          font: "blackcastle.ttf",
          size: 30,
          text: "",
          align: "center",
          verticalAlign: "center",
        },
        Button: {
          event: props.event,
        },
        GraphicsRect: true,
      }}
      updateValues={{
        Text: {
          text: props.text,
        },
      }}
      name={props.name}
    />
  );
};
