export const enemyAISystem = {
  components: ["Character", "EnemyAI"],
  advanceAI(actor) {
    if (!actor.Character.command) {
      let moves = ["UP", "DOWN", "LEFT", "RIGHT", "UPLEFT", "UPRIGHT", "DOWNLEFT", "DOWNRIGHT"];
      actor.Character.command = moves[Math.floor(Math.random() * moves.length)];
    }
  },
};
