import Engine from "./engine";

// a system runs system wide, accessing whatever components it needs
export const colliderSystem = {
  system: true,
  update() {
    let archetypes = Engine.getArchetypesWithComponent("Collider");

    for (let type of archetypes) {
      for (let actor of type.actors) {
        if (actor.Collider.tags && !actor.killed) {
          let attackBounds = Engine.getRectBounds(actor.Rect);

          for (let insideType of archetypes) {
            for (let insideActor of insideType.actors) {
              if (
                insideActor.Collider.mask &&
                Engine.arrayOverlaps(insideActor.Collider.mask, actor.Collider.tags) &&
                !insideActor.killed &&
                !actor.killed
              ) {
                let targetBounds = Engine.getRectBounds(insideActor.Rect);
                if (Engine.boundsIntersect(attackBounds, targetBounds)) {
                  Engine.handleEventForEngines("collision", {
                    target: insideActor,
                    attacker: actor,
                  });
                  Engine.handleEventForActor(insideActor.id, "actorCollision", {
                    target: insideActor,
                    attacker: actor,
                  });

                  if (insideActor.Collider.events) {
                    for (let event of insideActor.Collider.events) {
                      Engine.handleEventForEngines(event, {
                        target: insideActor,
                        attacker: actor,
                      });
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  },
};
