import React from "react";
import Engine from "../../engine";
import { isWalkableTileAt, getTileMap } from "../../tileMapEngine";

const moveUsingThreshold = (actor, threshold) => {
  let diffX = actor.PlayerMovement.currentTouchX - actor.PlayerMovement.startTouchX;
  let diffY = actor.PlayerMovement.currentTouchY - actor.PlayerMovement.startTouchY;

  if (Math.abs(diffX) > threshold && Math.abs(diffY) > threshold) {
    if (diffX > 0 && diffY < 0) {
      actor.Character.command = "UPRIGHT";
    }
    if (diffX > 0 && diffY > 0) {
      actor.Character.command = "DOWNRIGHT";
    }
    if (diffX < 0 && diffY > 0) {
      actor.Character.command = "DOWNLEFT";
    }
    if (diffX < 0 && diffY < 0) {
      actor.Character.command = "UPLEFT";
    }
  } else {
    if (Math.abs(diffX) > threshold) {
      if (diffX > 0) {
        actor.Character.command = "RIGHT";
      } else {
        actor.Character.command = "LEFT";
      }
    }

    if (Math.abs(diffY) > threshold) {
      if (diffY > 0) {
        actor.Character.command = "DOWN";
      } else {
        actor.Character.command = "UP";
      }
    }
  }
};

export const playerMovementEngine = ({ isWalkableTileAt }) => {
  return {
    components: ["Rect", "PlayerMovement", "Tweens", "Character"],
    update(actor) {
      if (actor.PlayerMovement.touchDown) {
        moveUsingThreshold(actor, 150);
      }
      if (actor.PlayerMovement.keyDown) {
        if (actor.PlayerMovement.keyDownTime == 0) {
          actor.PlayerMovement.keyDownTime = globalThis.__date_clock();
          actor.Character.command = actor.PlayerMovement.command;
        } else if (globalThis.__date_clock() - actor.PlayerMovement.keyDownTime > 200000) {
          actor.Character.command = actor.PlayerMovement.command;
        }
      }
    },
    keydown(actor, keycode) {
      actor.PlayerMovement.keyDown = true;
      actor.PlayerMovement.keyDownTime = 0;
      switch (keycode) {
        case 81:
          actor.PlayerMovement.command = "UPLEFT";
          return;
        case 87:
        case 265:
          actor.PlayerMovement.command = "UP";
          return;
        case 69:
          actor.PlayerMovement.command = "UPRIGHT";
          return;
        case 90:
          actor.PlayerMovement.command = "DOWNLEFT";
          return;
        case 88:
        case 264:
          actor.PlayerMovement.command = "DOWN";
          return;
        case 67:
          actor.PlayerMovement.command = "DOWNRIGHT";
          return;
        case 65:
        case 263:
          actor.PlayerMovement.command = "LEFT";
          return;
        case 68:
        case 262:
          actor.PlayerMovement.command = "RIGHT";
          return;
        default:
          return;
      }
    },
    keyup(actor, keycode) {
      actor.PlayerMovement.command = null;
      actor.PlayerMovement.keyDown = false;
    },

    touchstart({ PlayerMovement }, event) {
      PlayerMovement.startTouchX = event.x;
      PlayerMovement.startTouchY = event.y;
      PlayerMovement.currentTouchX = event.x;
      PlayerMovement.currentTouchY = event.y;
      PlayerMovement.touchDown = true;
    },
    touchmove({ PlayerMovement }, event) {
      PlayerMovement.currentTouchX = event.x;
      PlayerMovement.currentTouchY = event.y;
    },
    touchend(actor, event) {
      actor.PlayerMovement.touchDown = false;
      moveUsingThreshold(actor, 30);
    },
  };
};

export const playerItemEngine = {
  components: ["Item", "Position"],
  playerMoved(item, player) {
    if (item.Position.mapSeed != player.Position.mapSeed) {
      return;
    }
    if (item.Position.x == player.Position.x && item.Position.y == player.Position.y) {
      console.log("item: ", JSON.stringify(item));
      switch (item.Item.type) {
        case "stairdown":
          player.Character.availableAction = {
            name: "Go down",
            type: "goDownStairs",
            seed: item.Item.toSeed,
            toX: item.Item.toX,
            toY: item.Item.toY,
          };
          break;
        case "stairup":
          player.Character.availableAction = {
            name: "Go up",
            type: "goUpStairs",
            seed: item.Item.toSeed,
            toX: item.Item.toX,
            toY: item.Item.toY,
          };
          break;
        case "gold":
          console.log("gold! amount: " + item.Item.amount);
          player.Character.gold += item.Item.amount;
          Engine.killActor(item.id);
          break;
      }
    }
  },
};

let handleAction = (player) => {
  let availableAction = player.Character.availableAction;
  if (availableAction) {
    switch (availableAction.type) {
      case "goDownStairs":
      case "goUpStairs": {
        player.Position.mapSeed = availableAction.seed;
        Engine.handleEventForEngines("playerGoDownStairs", availableAction);
        break;
      }
    }
  }
  player.Character.availableAction = null;
};

export const characterActionEngine = {
  components: ["Character"],
  keydown(player, keyCode) {
    if (keyCode == 32) {
      handleAction(player);
    }
  },
  doPlayerAction: handleAction,
};

export default React.memo((props) => {
  let randX = 0;
  let randY = 0;
  let map = getTileMap(props.mapSeed);
  for (let i = 0; i < 20; i++) {
    randX = Math.floor(Math.random() * map.width);
    randY = Math.floor(Math.random() * map.height);
    if (isWalkableTileAt(props.mapSeed, randX, randY)) {
      break;
    }
  }

  return (
    <actor
      components={{
        Rect: {
          x: 0,
          y: 0,
          localX: randX * 32,
          localY: randY * 32,
        },
        ParentRect: props.world,
        Position: {
          mapSeed: props.mapSeed,
          x: randX,
          y: randY,
        },
        Tile: {
          index: 9 * 40 + 23,
        },
        Tweens: [],
        TweenQueue: [],
        PlayerMovement: {
          touchDown: false,
          keyDown: false,
          keyDownTime: 0,
          startTouchX: 0,
          startTouchY: 0,
          currentTouchX: 0,
          currentTouchY: 0,
          command: null,
        },
        Character: {
          availableAction: null,
          gold: 0,
          command: null,
          target: null,
          busy: false,
          wait: false,
          queueCount: 0,
          speed: 0.1,
          energy: 0,
          health: 10,
          hero: true,
          dead: false,
        },
      }}
      mapTo={props.mapTo}
      // updateValues={{
      //   Text: {
      //     text: props.text,
      //   },
      // }}
    />
  );
});
