import React from "react";
import ReactRenderer from "../reactRenderer";

//import message from "./module";
import * as Runtime from "runtime";

import Engine from "../engine";
import { blinkEngine } from "./components/BlinkText";
// engines

import {
  spriteEngine,
  graphicsEngine,
  velocityEngine,
  parentEngine,
  boundsKillerEngine,
  timeKillerEngine,
  textEngine,
  textBoxEngine,
  nativeSprite,
  nativeRect,
  tweenEngine,
  tileEngine,
} from "../standardEngines";

import { characterSystem, characterCommandSystem } from "./systems/characterSystem";
import { enemyAISystem } from "./systems/enemyAISystem";

import { tileMapEngine, isWalkableTileAt } from "../tileMapEngine";

import { colliderSystem } from "../colliderSystem";
import { reactEngine } from "../reactEngine";
import { playerMovementEngine, playerItemEngine, characterActionEngine } from "./components/Player";

import { buttonEngine } from "./components/ActionButton";

import { Game, mainGameEngine, createMainGame } from "./Game";

export const startGame = () => {
  Engine.registerNativeComponents([nativeRect, nativeSprite]);

  Engine.registerReactComponent("Game", Game);

  // --- game starts here

  let run = async () => {
    await Engine.loadFont("inter.ttf");
    await Engine.loadFont("blackcastle.ttf");

    Engine.loadTileTexture("tiles.png");

    let mainGame = createMainGame();

    // explicitly register all engines for visiblity and because order matters
    // also, do some plumping with dependency injection to set up all systems

    Engine.registerEngines({
      reactEngine,
      mainGameEngine,
      velocityEngine,
      parentEngine,
      boundsKillerEngine,
      timeKillerEngine,
      colliderSystem,
      graphicsEngine,
      textEngine,
      textBoxEngine,
      spriteEngine,
      tweenEngine,
      blinkEngine,
      tileMapEngine,
      tileEngine: tileEngine({
        getCurrentMapSeed: () => mainGame.MainGame.mapSeed,
      }),
      playerMovementEngine: playerMovementEngine({
        isWalkableTileAt,
      }),
      playerItemEngine,
      characterActionEngine,
      buttonEngine,
      characterSystem: characterSystem({
        isWalkableTileAt,
        getCurrentMapSeed: () => mainGame.MainGame.mapSeed,
      }),
      characterCommandSystem,
      enemyAISystem,
    });

    //await Engine.loadTextureAtlas("sprite.json");
    Engine.init();
    Engine.setClearColor(0.5, 0.2, 0, 1);
  };

  run();
};
